function add(id,d,title,core,rule,example,contrast,limit,source,questions){lessons.push({id,d,title,core,rule,example,contrast,limit,source,minutes:15,questions:questions.map((q,i)=>({id:id+'-q'+(i+1),text:q[0],answer:q[1],explanation:q[2],kind:'autoral'}))});}
add('seguridade','prev','Seguridade Social','Saúde, previdência e assistência são partes de um sistema de proteção.','O art. 194 da Constituição reúne ações dos poderes públicos e da sociedade. A saúde é direito de todos; a previdência tem caráter contributivo; a assistência atende quem dela necessitar, independentemente de contribuição. Universalidade da cobertura e do atendimento, seletividade e distributividade convivem no sistema.','Uma pessoa sem contribuições pode ser atendida pelo SUS. Isso não transforma o atendimento em aposentadoria nem afasta requisitos de um benefício previdenciário.','Seguridade é o conjunto; previdência é uma de suas áreas. Assistência e previdência não são sinônimos.','Universalidade não significa concessão de qualquer benefício a qualquer pessoa. Cada prestação tem requisitos próprios.','cf',[
['A seguridade compreende saúde, previdência e assistência social.',true,'As três áreas estão no art. 194 da Constituição.'],['A assistência social exige contribuição previdenciária prévia.',false,'O art. 203 prevê assistência independentemente de contribuição.'],['A organização da seguridade admite iniciativas da sociedade.',true,'O art. 194 menciona poderes públicos e sociedade.'],['Universalidade dispensa os requisitos legais de todos os benefícios.',false,'O objetivo constitucional não elimina requisitos de cada prestação.']]);
add('legislacao','prev','Legislação: fontes e aplicação','Localize a norma adequada antes de aplicar uma regra.','A Constituição está acima das leis e regulamentos. As Leis 8.212 e 8.213 tratam de custeio e benefícios, respectivamente; o Decreto 3.048 regulamenta a previdência. A aplicação exige observar vigência, hierarquia, fatos e regras de transição. Uma instrução normativa não pode contrariar a lei.','Para examinar um benefício, identifique quando ocorreram os fatos e qual regra incidia, antes de usar um resumo recente.','Lei de custeio não é lei de benefícios. Norma nova não apaga automaticamente direito adquirido.','Não presuma que toda mudança se aplica retroativamente. Compare o caso e as disposições de transição.','r',[
['Um regulamento pode contrariar livremente a lei que regulamenta.',false,'A regulamentação está subordinada à lei.'],['A Lei 8.213/1991 disciplina o Plano de Benefícios.',true,'É uma das fontes centrais para benefícios do RGPS.'],['A data dos fatos pode influenciar a regra previdenciária aplicável.',true,'Vigência, direito adquirido e transições precisam ser considerados.'],['Lei de custeio e lei de benefícios têm objeto idêntico.',false,'Os objetos se relacionam, mas não se confundem.']]);
add('segurados','prev','Segurados obrigatórios','A atividade remunerada enquadrada em lei gera filiação obrigatória.','As categorias incluem empregado, empregado doméstico, contribuinte individual, trabalhador avulso e segurado especial. Classifique pelos fatos da atividade, e não somente pelo nome do contrato. O empregado reúne elementos de vínculo; o contribuinte individual inclui diversas atividades por conta própria.','Um profissional que trabalha por conta própria pode ser contribuinte individual; o simples rótulo de autônomo não afasta um vínculo de emprego comprovado.','Segurado especial não é sinônimo de qualquer trabalhador rural. Trabalhador avulso e contribuinte individual têm regimes próprios.','Situações especiais exigem a leitura dos requisitos da categoria no art. 11 da Lei 8.213.','p',[
['O enquadramento depende das características efetivas da atividade.',true,'Os fatos e requisitos legais definem a categoria.'],['Toda pessoa que trabalha no meio rural é segurada especial.',false,'Há requisitos específicos para o segurado especial.'],['Empregado doméstico integra as categorias de segurados obrigatórios.',true,'A categoria é expressamente prevista.'],['O nome do contrato, sozinho, decide sempre o enquadramento.',false,'A realidade da atividade precisa ser examinada.']]);
add('filiacao','prev','Filiação e inscrição','Vínculo jurídico e cadastro são conceitos diferentes.','Para o segurado obrigatório, a filiação decorre do exercício da atividade enquadrada no RGPS. Inscrição é o ato de cadastramento. No facultativo, a filiação depende da inscrição formalizada com o primeiro recolhimento válido, conforme o regulamento.','Uma pessoa começa atividade como empregada: sua filiação não espera que ela escolha voluntariamente contribuir.','Filiação é vínculo de proteção e obrigações; inscrição é registro. Não confunda com o número de contribuições exigido para carência.','Recolhimentos em atraso e situações de facultativo exigem análise própria; não retroaja a filiação por suposição.','r',[
['A inscrição corresponde ao cadastramento do segurado.',true,'É distinta do vínculo de filiação.'],['O empregado só se filia se optar expressamente pelo RGPS.',false,'A filiação é obrigatória quando a atividade é enquadrada.'],['Filiação e carência são conceitos diferentes.',true,'Uma é vínculo; a outra é requisito contributivo para certas prestações.'],['Inscrição e filiação são sempre o mesmo ato para todas as categorias.',false,'O modo de formação da filiação depende da categoria.']]);
add('qualidade','prev','Qualidade de segurado e período de graça','A proteção pode continuar por prazo legal sem contribuição.','O art. 15 da Lei 8.213 descreve hipóteses de manutenção da qualidade. O chamado período de graça permite preservação em certas situações. A duração varia conforme a hipótese; pode haver prorrogações condicionadas. Não aplique um prazo único a todos.','Alguém deixa de exercer atividade e pode manter a qualidade por período legal. Isso não acrescenta automaticamente uma contribuição à sua carência.','Qualidade de segurado é condição de proteção; carência é exigência contributiva. Período de graça não é pagamento presumido.','Para calcular a perda, confira a categoria, as prorrogações e o marco de perda no §4º do art. 15.','p',[
['Toda interrupção de contribuições causa perda imediata da qualidade.',false,'A lei prevê hipóteses de manutenção sem recolhimentos.'],['A duração da manutenção depende da hipótese legal.',true,'Não existe um único prazo aplicável a todas as situações.'],['O período de graça cria contribuições mensais fictícias para carência.',false,'Manutenção da proteção não equivale a recolhimento.'],['Qualidade de segurado e carência devem ser analisadas separadamente.',true,'São requisitos distintos.']]);
add('carencia','prev','Carência','Carência é um requisito específico, não uma promessa de benefício.','O art. 24 conceitua carência como número mínimo de contribuições mensais indispensáveis para o benefício, consideradas segundo as regras legais. Há benefícios com dispensa e regras específicas de contagem, início e reaproveitamento. Cumprir carência não dispensa os demais requisitos.','Em hipótese didática com exigência de 12 contribuições, 11 contribuições não viram 12 apenas por manter a qualidade de segurado.','Carência não é sinônimo de tempo de contribuição, qualidade ou período de graça.','Verifique o benefício, a categoria, as dispensas e a legislação vigente. Não memorize uma lista de prazos sem conferir alterações e decisões aplicáveis.','p',[
['Cumprir carência assegura todo benefício sem outros requisitos.',false,'Os requisitos da prestação precisam ser satisfeitos em conjunto.'],['Qualidade de segurado substitui automaticamente a carência.',false,'São condições diferentes.'],['A lei pode dispensar carência em determinadas hipóteses.',true,'As hipóteses de dispensa são legais e específicas.'],['A contagem da carência exige observar a categoria do segurado.',true,'O modo de contar não é uniforme em todas as situações.']]);
add('salario','prev','Salário de contribuição','É a base de cálculo das contribuições, conforme a categoria.','O art. 28 da Lei 8.212 define salário de contribuição e parcelas integrantes e excluídas. Para empregados, parte-se da remuneração de natureza legalmente incluída. A denominação da verba não basta: confira natureza, requisitos e exclusões. Limites e valores monetários variam no tempo.','Em um caso com salário e reembolso de despesa, analise cada parcela separadamente; não some tudo só porque aparece no contracheque.','Salário de contribuição, salário de benefício e renda mensal do benefício têm funções distintas.','Não fixe valores de teto ou alíquotas anuais sem consultar o ato vigente. Contribuições abaixo do mínimo podem exigir ajustes conforme a hipótese.','c',[
['Toda verba recebida integra a base, sem qualquer exclusão.',false,'Há exclusões legais e requisitos próprios.'],['Salário de contribuição é igual ao valor de todo benefício concedido.',false,'Base contributiva e renda do benefício não se confundem.'],['A natureza e os requisitos da parcela importam para sua inclusão.',true,'A classificação deve seguir a lei, não só o nome da verba.'],['O teto aplicável deve ser conferido na competência analisada.',true,'Os limites monetários podem ser reajustados.']]);
add('facultativo','prev','Facultativo e exclusões do RGPS','A filiação facultativa não substitui a obrigatória.','O facultativo se filia por ato voluntário quando preenche os requisitos e não exerce atividade que o enquadre como obrigatório. A idade mínima regulamentar é 16 anos. Participantes de RPPS estão sujeitos à vedação constitucional de filiação facultativa ao RGPS, observadas as situações normativas aplicáveis.','Estudante sem atividade remunerada pode analisar a filiação facultativa. Quem começa atividade obrigatória deve observar o enquadramento correspondente.','Ausência de emprego formal não significa ausência de atividade obrigatória: o trabalho por conta própria pode gerar filiação.','Não classifique automaticamente todo desempregado ou servidor como facultativo. Verifique atividade e regime.','r',[
['Trabalhar por conta própria pode gerar filiação obrigatória.',true,'Emprego formal não é a única fonte de filiação.'],['Quem exerce atividade obrigatória pode escolher livremente ser facultativo nessa atividade.',false,'O enquadramento obrigatório não é substituído por escolha.'],['O facultativo tem os mesmos pressupostos de enquadramento do empregado.',false,'A filiação facultativa tem requisitos próprios.'],['Antes de filiar como facultativo é preciso verificar eventual atividade obrigatória.',true,'Essa verificação evita enquadramento incorreto.']]);
add('custeio','prev','Empresa, custeio e recolhimento','Seguridade é financiada por toda a sociedade.','O art. 195 da Constituição organiza o financiamento direto e indireto. A Lei 8.212 disciplina contribuições, empresa, empregador doméstico e obrigações. Recolher, arrecadar e conceder benefício são atividades distintas. A Receita Federal exerce atribuições de administração tributária das contribuições; o INSS atua no reconhecimento e manutenção de benefícios do RGPS.','Ao analisar uma folha, separe o segurado, o responsável pelo desconto, o recolhimento e a competência administrativa.','Contribuição do trabalhador não é a única fonte de receita. INSS e Receita Federal não são o mesmo órgão.','Alíquotas, vencimentos e encargos dependem da categoria e da norma da competência. Não use um prazo universal.','c',[
['A seguridade é financiada somente por contribuições dos empregados.',false,'O financiamento é diversificado e envolve toda a sociedade.'],['É necessário separar o contribuinte do responsável pelo recolhimento.',true,'As posições podem ter sujeitos diferentes.'],['INSS e Receita Federal exercem exatamente as mesmas competências.',false,'Benefícios e administração tributária são campos distintos.'],['Uma regra de recolhimento pode depender da categoria analisada.',true,'A identificação do sujeito e da competência é essencial.']]);
add('beneficiarios','prev','Beneficiários e prestações','Beneficiários abrangem segurados e dependentes.','A Lei 8.213 distingue segurados e dependentes e organiza benefícios e serviços. Dependência exige observar classes, condições e a hipótese de presunção ou prova. Não basta relação afetiva genérica. O evento protegido, a qualidade, a carência quando exigida e os demais requisitos compõem a análise de concessão.','Na pensão por morte, examine o falecimento, a situação previdenciária do instituidor e a condição do dependente.','Benefício em dinheiro não é sinônimo de serviço previdenciário; segurado não é sinônimo de dependente.','Classes de dependentes, durações e regras de cada benefício devem ser aprofundadas no texto legal aplicável.','p',[
['Segurados e dependentes integram os beneficiários do RGPS.',true,'A lei diferencia essas duas categorias.'],['Qualquer relação afetiva dá automaticamente direito a todas as prestações.',false,'É preciso enquadramento e preenchimento dos requisitos legais.'],['Os requisitos variam conforme o benefício e o evento protegido.',true,'A análise deve ser específica.'],['Serviço e benefício previdenciário são termos necessariamente idênticos.',false,'As prestações incluem categorias distintas.']]);
add('beneficios','prev','Benefícios, cálculo e reabilitação','Identifique a contingência antes de escolher a prestação.','O Plano de Benefícios contempla aposentadorias, benefícios por incapacidade, pensão, salário-maternidade, auxílio-reclusão e outras prestações previstas. O cálculo depende da regra e do momento aplicável, inclusive EC 103/2019 e transições. Serviço social e reabilitação profissional têm finalidade de orientação e reinserção, conforme os requisitos.','Incapacidade temporária e permanente pedem exames distintos; diagnóstico médico, por si só, não define todos os requisitos previdenciários.','Salário de benefício é elemento de cálculo; renda mensal é o resultado da regra de concessão. Reabilitação não é apenas pagamento.','Este é um módulo introdutório. Use a fonte para aprofundar requisitos, cálculo, reajuste, acumulações e legislações especiais.','p',[
['Todas as aposentadorias têm fórmula única, imutável no tempo.',false,'Há regras distintas, alterações e transições.'],['O evento protegido ajuda a identificar a prestação adequada.',true,'É o ponto de partida para verificar os requisitos.'],['Reabilitação profissional tem finalidade além de transferência de renda.',true,'Relaciona-se à reinserção profissional nas condições legais.'],['Um diagnóstico médico dispensa qualquer outro requisito previdenciário.',false,'Os demais requisitos precisam ser examinados.']]);
add('bpc','prev','LOAS, BPC e Auxílio-Inclusão','BPC é assistencial, não aposentadoria.','A LOAS disciplina o benefício de prestação continuada a idosos e pessoas com deficiência que preencham os requisitos. A concessão não exige contribuição previdenciária prévia. A avaliação e os critérios legais vão além de uma impressão genérica de pobreza. Auxílio-Inclusão possui regras próprias e não é sinônimo de BPC.','Uma pessoa pode buscar BPC sem ter contribuído, mas precisa atender aos critérios legais da prestação.','BPC não é aposentadoria contributiva e não gera pensão por morte como benefício previdenciário.','Critérios de renda, deficiência, avaliação e acumulação devem ser conferidos na lei e regulamentação atuais.','b',[
['BPC é uma aposentadoria do RGPS.',false,'Sua natureza é assistencial.'],['A contribuição prévia ao RGPS é requisito geral do BPC.',false,'O benefício independe de contribuição previdenciária.'],['A concessão do BPC depende de requisitos legais.',true,'Natureza assistencial não significa concessão incondicionada.'],['Auxílio-Inclusão e BPC possuem disciplina própria.',true,'Não devem ser tratados como uma única prestação.']]);
add('regimes','prev','RPPS, CTC e contagem recíproca','Tempo entre regimes exige regras de certificação e compensação.','RGPS e RPPS têm sujeitos e regras próprios. A contagem recíproca permite aproveitamento de tempo conforme a Constituição e a legislação, mediante certificação e compensação quando cabíveis. Um mesmo tempo não pode ser contado em duplicidade para gerar duas vantagens incompatíveis.','Antes de levar tempo de um regime para outro, verifique a certidão, o uso anterior e os períodos abrangidos.','CTC certifica tempo; não é, por si só, concessão automática de aposentadoria.','Confira regras constitucionais, EC 103/2019, vedação de dupla contagem e legislação de compensação.','cf',[
['CTC equivale à concessão automática de aposentadoria.',false,'A certidão e o benefício cumprem funções diferentes.'],['É preciso verificar se o tempo já foi utilizado.',true,'A contagem exige evitar aproveitamento vedado.'],['RGPS e RPPS são o mesmo regime com dois nomes.',false,'São regimes distintos.'],['Contagem recíproca exige observância de requisitos legais.',true,'Não é transferência livre e irrestrita de períodos.']]);
add('prazos','prev','Decadência, prescrição, crimes e recursos','Institutos diferentes precisam de análise separada.','Decadência e prescrição têm objetos e marcos de contagem específicos; não transporte um prazo de revisão de benefício para qualquer cobrança. Crimes previdenciários exigem elementos do tipo penal. Recursos administrativos seguem competência e procedimento próprios, com contraditório e motivação.','Em uma revisão de benefício, identifique qual direito é discutido e o marco legal antes de contar um prazo.','Prazo tributário, revisão previdenciária e prescrição de parcelas não se confundem. Inadimplemento não autoriza presumir todo elemento de um crime.','Módulo de orientação: aprofunde cada prazo, exceção e jurisprudência na fonte pertinente antes de resolver casos complexos.','p',[
['Todo prazo previdenciário tem o mesmo início e a mesma duração.',false,'Institutos e hipóteses têm disciplina específica.'],['O objeto do pedido importa para identificar o prazo aplicável.',true,'É preciso qualificar a situação antes de contar.'],['Qualquer dívida previdenciária prova automaticamente um crime.',false,'Responsabilidade penal exige os elementos do tipo.'],['Recursos administrativos devem observar o procedimento aplicável.',true,'Competência, prazo e forma precisam ser conferidos.']]);
add('direitos','const','Direitos fundamentais: igualdade e legalidade','Leia o alcance da regra e as condições de restrição.','O art. 5º protege direitos e garantias individuais e coletivos. Pela legalidade, ninguém é obrigado a fazer ou deixar de fazer algo senão em virtude de lei. Igualdade não impede diferenciações constitucionalmente justificadas. Direitos não devem ser generalizados como absolutos sem análise.','Uma exigência imposta pelo Estado precisa de fundamento normativo adequado; preferências pessoais do agente não bastam.','Igualdade jurídica não é proibição de toda diferenciação. Legalidade para o particular e atuação vinculada da Administração têm contextos próprios.','Examine titularidade, âmbito de proteção, reserva legal, limites e exceções de cada inciso.','cf',[
['Igualdade proíbe toda diferenciação, qualquer que seja a justificativa.',false,'Há diferenciações constitucionalmente legítimas.'],['O art. 5º prevê garantia de legalidade.',true,'O inciso II condiciona obrigações à lei.'],['Toda vontade pessoal de um agente público basta para criar obrigação.',false,'É necessário fundamento jurídico adequado.'],['A leitura do direito deve considerar seu âmbito de proteção e limites.',true,'Evita extrapolações a partir de frases isoladas.']]);
add('garantias','const','Prisão e garantias processuais','Não confunda investigação, prisão e condenação definitiva.','Ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória. Isso não exclui toda prisão cautelar legalmente cabível. Prisão em flagrante e por ordem judicial obedecem às hipóteses constitucionais, com exceções previstas para matéria militar. O preso tem direitos, inclusive silêncio e assistência.','Dizer que alguém está investigado não permite tratá-lo como definitivamente condenado. Uma cautelar exige fundamento próprio.','Presunção de inocência não é imunidade absoluta a medida cautelar. Silêncio não equivale a confissão.','Leia os incisos LVII, LXI a LXIV e LVIII. Identificação criminal admite hipóteses legais mesmo para o civilmente identificado.','cf',[
['A presunção de inocência elimina toda possibilidade de prisão cautelar.',false,'Prisões cautelares cabíveis têm requisitos próprios.'],['O preso tem direito ao silêncio.',true,'É garantia constitucional expressa.'],['Ser investigado equivale a condenação definitiva.',false,'Investigação e condenação são fases e situações diferentes.'],['A identificação criminal do civilmente identificado admite hipóteses legais.',true,'O inciso LVIII ressalva as hipóteses previstas em lei.']]);
add('remedios','const','Garantias e remédios constitucionais','Escolha a garantia pelo direito e pelo tipo de lesão.','Habeas corpus protege a liberdade de locomoção contra ilegalidade ou abuso de poder. Habeas data tem objeto ligado a dados pessoais nas hipóteses constitucionais. Mandado de segurança protege direito líquido e certo não amparado por habeas corpus ou habeas data, nas condições constitucionais.','Uma ameaça ilegal à locomoção pede análise distinta de um pedido de acesso a dados pessoais.','Habeas corpus não é remédio universal para qualquer insatisfação. Mandado de injunção e ação popular têm objetos próprios.','Compare o objeto, a legitimidade e os pressupostos; não escolha somente pelo nome do instrumento.','cf',[
['Habeas corpus se relaciona à liberdade de locomoção.',true,'Esse é seu campo constitucional de proteção.'],['Habeas data substitui qualquer ação sobre patrimônio.',false,'Seu objeto constitucional é específico.'],['Todo direito pode ser protegido pelo mesmo remédio, sem requisitos.',false,'Cada instrumento tem pressupostos e objeto próprios.'],['É necessário identificar a lesão para selecionar a garantia adequada.',true,'O problema determina o instrumento cabível.']]);
add('sociais','const','Direitos sociais, nacionalidade e cidadania','Nacionalidade, direitos políticos e direitos sociais não se confundem.','O art. 6º reúne direitos sociais; os arts. 12 a 16 tratam de nacionalidade e direitos políticos. Nacionalidade é vínculo jurídico-político com o Estado. Exercício de direitos políticos tem requisitos próprios. A Constituição diferencia brasileiros natos e naturalizados nas hipóteses que estabelece.','Ter nacionalidade brasileira não elimina requisitos de idade e alistamento para exercer certos direitos políticos.','Cidadania em sentido político, nacionalidade e residência são conceitos diferentes.','Confira as hipóteses constitucionais, inclusive alterações de nacionalidade; não presuma que toda distinção entre nato e naturalizado é permitida.','cf',[
['Nacionalidade e residência são necessariamente a mesma condição.',false,'O vínculo jurídico-político não é mero endereço.'],['A Constituição prevê direitos sociais.',true,'O art. 6º é uma referência central.'],['O exercício de direitos políticos pode exigir requisitos específicos.',true,'Há condições constitucionais e legais.'],['Qualquer lei pode inventar livremente novas distinções entre nato e naturalizado.',false,'O art. 12, §2º limita essas distinções às hipóteses constitucionais.']]);
add('administracao','const','Administração Pública: arts. 37 a 41','Princípios e requisitos constitucionais orientam a atuação administrativa.','Legalidade, impessoalidade, moralidade, publicidade e eficiência são princípios expressos no art. 37. O concurso é a regra de acesso a cargos e empregos, com exceções constitucionais. Acumulação remunerada tem vedações e exceções específicas, inclusive compatibilidade de horários nas hipóteses pertinentes.','Uma nomeação precisa ser examinada pelo tipo de cargo, exigência de concurso e normas constitucionais aplicáveis.','Publicidade não autoriza promoção pessoal. Eficiência não afasta legalidade.','Aprofunde servidores, remuneração, teto, acumulação, responsabilidade e estabilidade; as exceções não são autorização geral.','cf',[
['Eficiência permite descumprir a lei sempre que o agente achar útil.',false,'Os princípios devem ser observados conjuntamente.'],['Publicidade é um princípio expresso da Administração.',true,'Está no caput do art. 37.'],['Promoção pessoal do agente é o objetivo da publicidade institucional.',false,'A publicidade deve respeitar a impessoalidade.'],['A exigência de concurso possui exceções constitucionais específicas.',true,'A regra e suas exceções precisam ser diferenciadas.']]);
add('organizacao','adm','Estado, princípios e organização','Órgãos e entidades ocupam posições distintas na Administração.','A Administração Direta se compõe de órgãos dos entes federativos. A Indireta inclui entidades como autarquias, fundações, empresas públicas e sociedades de economia mista. Desconcentração distribui competências dentro de uma pessoa; descentralização envolve outra pessoa ou delegação nas condições legais.','Criar um departamento dentro de uma autarquia é diferente de criar uma nova autarquia.','Órgão não é uma pessoa jurídica separada. Vinculação da entidade não é hierarquia idêntica à de departamentos.','A natureza jurídica da entidade importa para regime de pessoal, prerrogativas e forma de criação.','cf',[
['Órgão e entidade são sempre pessoas jurídicas idênticas.',false,'Órgãos integram a estrutura de uma pessoa.'],['Uma autarquia integra a Administração Indireta.',true,'É uma das entidades típicas.'],['Desconcentração ocorre dentro da mesma pessoa jurídica.',true,'É distribuição interna de competências.'],['Criar um departamento equivale necessariamente a criar nova entidade.',false,'É possível reorganização interna sem nova pessoa.']]);
add('atos','adm','Atos administrativos','Examine competência, finalidade, forma, motivo e objeto.','A validade exige atender aos elementos legais. Anulação enfrenta ilegalidade; revogação trata de conveniência e oportunidade, respeitados os limites. A Lei 9.784 prevê convalidação de defeitos sanáveis quando presentes as condições. Nem todo ato possui todos os atributos na mesma extensão.','Uma licença ilegal deve ser analisada por legalidade, e não somente por desagrado com seu resultado.','Motivo são pressupostos de fato e direito; motivação é sua exteriorização. Anular e revogar não são sinônimos.','Respeite direitos adquiridos, segurança jurídica, decadência quando aplicável e devido processo.','a',[
['Anulação e revogação têm o mesmo fundamento.',false,'Ilegalidade e mérito são fundamentos distintos.'],['A competência é um dos elementos do ato.',true,'Integra a análise de validade.'],['Toda ilegalidade pode ser ignorada por conveniência administrativa.',false,'A atuação deve observar a legalidade e o regime de invalidação.'],['Motivação exterioriza razões do ato.',true,'Não se confunde com o pressuposto material chamado motivo.']]);
add('poderes','adm','Poderes e abuso de poder','Competência é instrumento para a finalidade pública.','Poder hierárquico organiza relações internas; disciplinar alcança infrações nas relações pertinentes; regulamentar permite atos normativos subordinados à lei; poder de polícia condiciona direitos e atividades em favor do interesse público. Excesso de poder envolve competência; desvio de finalidade envolve objetivo inadequado.','Um agente competente para fiscalizar não pode usar a atuação para perseguir um desafeto.','Discricionariedade não é arbitrariedade. Sanção de polícia e punição disciplinar não são sempre a mesma relação.','Toda medida deve respeitar fundamento legal, finalidade, proporcionalidade e procedimento.','a',[
['Discricionariedade autoriza arbitrariedade sem controle.',false,'A margem de escolha continua vinculada ao Direito.'],['Perseguir desafeto pode caracterizar desvio de finalidade.',true,'O objetivo se afasta da finalidade pública.'],['Poder regulamentar permite contrariar qualquer lei.',false,'O regulamento se subordina ao regime legal.'],['A proporcionalidade importa no exercício do poder de polícia.',true,'Restrições devem respeitar limites jurídicos.']]);
add('delegacao','adm','Delegação do poder de polícia','Não generalize nem a proibição nem a autorização de delegar.','No Tema 532, o STF admite delegação por lei a pessoas jurídicas de direito privado da Administração Indireta, de capital majoritariamente público, que prestem exclusivamente serviço público de atuação própria do Estado e em regime não concorrencial. Todos esses requisitos importam.','Uma entidade da Indireta não está automaticamente autorizada: examine lei, capital, atividade e regime de atuação.','Atividade material de apoio não equivale necessariamente a transferência de poder decisório ou sancionador.','A tese não autoriza delegação irrestrita a qualquer empresa privada. Leia a tese e o caso.','stf',[
['A tese do Tema 532 autoriza delegação irrestrita a qualquer empresa.',false,'Há requisitos específicos e cumulativos.'],['A lei é um dos pressupostos da delegação admitida na tese.',true,'A delegação mencionada depende de lei.'],['A condição de integrante da Indireta, sozinha, basta para toda delegação.',false,'Também importam capital, serviço e regime de atuação.'],['Apoio material e competência decisória precisam ser distinguidos.',true,'Não são transferências necessariamente equivalentes.']]);
add('servidores','adm','Agentes públicos e Lei 8.112','O regime do servidor distingue ingresso, movimentação e responsabilidade.','A Lei 8.112 rege servidores civis federais nos sujeitos indicados em seu art. 1º. Provimento preenche cargo; vacância o deixa vago. Remoção e redistribuição têm objetos diferentes. Direitos, vantagens, deveres e proibições compõem o regime estatutário. Responsabilidade pode envolver esferas administrativa, civil e penal.','Antes de classificar uma transferência, pergunte se o objeto é o servidor ou o cargo.','Cargo, emprego e função não são termos intercambiáveis. Remoção do servidor não é redistribuição do cargo.','Prazos, licenças, penalidades e hipóteses de provimento exigem estudo detalhado dos artigos.','s',[
['Remoção e redistribuição são institutos indistintos.',false,'Têm objetos e requisitos próprios.'],['A Lei 8.112 prevê deveres e proibições funcionais.',true,'Integram o regime disciplinar.'],['Cargo público e emprego público são sempre a mesma relação jurídica.',false,'Os regimes podem diferir.'],['É necessário distinguir provimento de vacância.',true,'Preenchimento e desocupação são ideias distintas.']]);
add('controle','adm','Serviços, controle e responsabilidade','Controle e responsabilização têm fundamento e limites.','O controle pode ser administrativo, legislativo e judicial. O Judiciário examina juridicidade; não substitui livremente a Administração em toda escolha legítima de mérito. Responsabilidade estatal deve ser examinada pelos requisitos constitucionais e pelo tipo de caso. Serviços públicos podem ter execução delegada nas formas admitidas.','Ato discricionário com desvio de finalidade continua sujeito a controle de legalidade.','Delegar execução de serviço não elimina o regime público aplicável. Responsabilidade do Estado não dispensa análise de nexo e excludentes.','Aprofunde concessões, permissões, responsabilidade, processo e improbidade na lei vigente.','cf',[
['Ato discricionário nunca pode ter sua legalidade controlada.',false,'Discricionariedade não afasta controle de juridicidade.'],['Existem controles administrativo, legislativo e judicial.',true,'São classificações centrais.'],['Delegar execução elimina automaticamente todos os deveres públicos.',false,'A delegação segue regime e fiscalização aplicáveis.'],['O caso concreto importa para avaliar responsabilidade estatal.',true,'Requisitos e excludentes precisam ser considerados.']]);
add('processo','adm','Processo administrativo e improbidade','Decisões públicas exigem garantias e fundamento adequado.','A Lei 9.784 disciplina o processo administrativo federal, com princípios, direitos do administrado, competência, motivação e recursos. A improbidade possui disciplina própria na Lei 8.429, alterada pela Lei 14.230/2021, e não se confunde com toda irregularidade ou mero mau resultado.','Antes de sancionar, identifique base legal, conduta, requisitos e possibilidade de defesa.','Ilegalidade, infração disciplinar, crime e improbidade não são automaticamente equivalentes.','Este módulo orienta a leitura. Consulte a lei específica e jurisprudência para dolo, tipicidade, prazos e sanções de improbidade.','a',[
['Toda irregularidade administrativa constitui automaticamente improbidade.',false,'Há requisitos próprios na legislação de improbidade.'],['A motivação é relevante para o processo administrativo.',true,'A lei prevê sua exigência nas hipóteses pertinentes.'],['Defesa e procedimento são dispensáveis em qualquer sanção.',false,'Garantias processuais precisam ser respeitadas.'],['Infração disciplinar e crime são categorias diferentes.',true,'Não se presume equivalência automática.']]);
add('interpretacao','port','Interpretação e tipologia textual','O texto limita o que pode ser concluído.','Separe informação explícita, inferência sustentada e extrapolação. Identifique tema, tese, argumentos, finalidade e gênero. Narração organiza acontecimentos; descrição apresenta características; argumentação defende uma posição. Um texto pode combinar sequências.','Texto: "Alguns atendimentos foram remarcados." Não se pode concluir que todos foram remarcados.','Possibilidade não é certeza; alguns não é todos; causa não é mera sequência temporal.','Conhecimento de mundo não autoriza atribuir ao autor uma afirmação sem suporte textual.','pt',[
['De "alguns pedidos foram deferidos" decorre que todos foram deferidos.',false,'A generalização não está autorizada.'],['Uma inferência deve ter apoio no texto.',true,'Não basta ser plausível no mundo real.'],['Um texto pode combinar narração e descrição.',true,'As sequências textuais podem coexistir.'],['Opinião pessoal do leitor substitui a posição expressa pelo autor.',false,'A interpretação exige respeitar o texto.']]);
add('classes','port','Classes, advérbios e relações de sentido','A função da palavra depende do contexto.','Substantivos nomeiam; verbos estruturam predicações; advérbios podem modificar verbo, adjetivo ou outro advérbio. Conjunções articulam relações como adição, oposição, causa, condição e concessão. Identificar a relação de sentido é mais útil que decorar uma lista sem contexto.','"Estudou, mas não revisou": "mas" articula oposição. Em "muito atento", "muito" intensifica um adjetivo.','Classe morfológica e função sintática são análises diferentes. A mesma forma pode assumir papéis distintos.','Substituir um conector pode alterar o sentido mesmo mantendo uma frase gramatical.','pt',[
['Em "muito atento", "muito" intensifica um adjetivo.',true,'O advérbio não se limita a modificar verbos.'],['Trocar "mas" por "portanto" preserva sempre a relação de sentido.',false,'Oposição e conclusão não são relações equivalentes.'],['Classe e função sintática são necessariamente a mesma classificação.',false,'São planos diferentes de análise.'],['O contexto ajuda a determinar o valor de um conector.',true,'A relação depende do enunciado.']]);
add('sintaxe','port','Sintaxe e concordância','Encontre o núcleo antes de concordar.','Localize sujeito, verbo e complementos. O núcleo do sujeito orienta a concordância nas construções usuais. "Haver" com sentido de existir é impessoal e fica no singular. "Existir" tem sujeito e concorda com ele. Adjetivos se relacionam aos termos a que se referem.','"Havia muitos pedidos" e "Existiam muitos pedidos" são construções corretas com regras diferentes.','Palavra próxima do verbo não é necessariamente o núcleo do sujeito. Concordância não se resolve só pela proximidade.','Há construções especiais, sujeitos compostos e possibilidades de concordância que exigem análise própria.','pt',[
['Em "Havia documentos", o uso singular de "haver" está correto.',true,'Com sentido de existir, o verbo é impessoal.'],['"Existia muitos documentos" segue a concordância padrão.',false,'O verbo existir concorda com o sujeito plural: existiam.'],['É útil localizar o núcleo do sujeito antes de flexionar o verbo.',true,'Essa identificação orienta a regra geral.'],['O termo mais próximo do verbo é sempre o sujeito.',false,'Proximidade não prova função sintática.']]);
add('regencia','port','Regência e crase','Crase exige o encontro de dois elementos, não apenas palavra feminina.','A regência determina a preposição exigida. A crase indicada pelo acento grave decorre de fusão, frequentemente entre preposição "a" e artigo "a(s)". Examine o termo regente e a possibilidade de artigo no termo seguinte. Há locuções e casos específicos.','"Entregou o documento à diretora": quem entrega algo a alguém pode produzir preposição a + artigo a.','Regência verbal não é concordância verbal. Palavra feminina, isoladamente, não prova crase.','Não aplique um teste mecânico sem considerar sentido, artigo e construção.','pt',[
['Toda palavra feminina deve ser precedida de acento grave.',false,'É preciso verificar os elementos da construção.'],['A regência ajuda a verificar a necessidade de preposição.',true,'É uma etapa central da análise da crase.'],['Regência e concordância resolvem exatamente o mesmo problema.',false,'Relação preposicional e flexão são análises distintas.'],['Em "entregou à diretora", pode ocorrer preposição a somada ao artigo a.',true,'A construção admite a fusão indicada pelo acento grave.']]);
add('escrita','port','Pontuação, ortografia e redação oficial','Escreva com estrutura, clareza e adequação.','A vírgula organiza relações sintáticas e sentido; não representa apenas pausa respiratória. Na ordem direta, não se separa sujeito de predicado por vírgula sem termo intercalado. Acentuação e ortografia seguem regras próprias. Redação oficial valoriza clareza, concisão, impessoalidade e padrão adequado.','"Os servidores analisaram os pedidos" não pede vírgula entre sujeito e verbo. Uma intercalação pode aparecer entre vírgulas.','Concisão não é omitir informação essencial. Formalidade não exige linguagem obscura.','Estude separadamente regras de acentuação, ortografia, significação e padrões documentais do manual.','pt',[
['A vírgula é determinada apenas pelo lugar em que se respira.',false,'Estrutura e sentido são critérios essenciais.'],['Clareza é um atributo relevante da redação oficial.',true,'O texto deve comunicar com precisão.'],['Formalidade exige tornar o texto propositalmente difícil.',false,'Formalidade convive com clareza e simplicidade.'],['Termos intercalados podem ser delimitados por vírgulas.',true,'A pontuação sinaliza a inserção.']]);
add('proposicoes','rlm','Proposições e tabelas-verdade','Uma proposição pode receber valor verdadeiro ou falso.','Sentenças declarativas com valor lógico são proposições no modelo clássico. Perguntas e ordens, em geral, não o são. Com n proposições simples independentes, a tabela completa tem 2 elevado a n linhas. Formalize símbolos antes de preencher a tabela.','Para p e q independentes, teste VV, VF, FV e FF: quatro linhas.','Uma frase conter a palavra "não" não a torna automaticamente falsa. Verdade factual e forma lógica são planos diferentes.','Identifique sentenças abertas e variáveis antes de atribuir valor lógico.','logic',[
['Uma tabela completa com duas proposições independentes tem quatro linhas.',true,'O número é 2² = 4.'],['Toda pergunta é uma proposição com valor lógico clássico.',false,'Perguntas não recebem, em geral, valor verdadeiro ou falso.'],['A presença de "não" torna toda frase falsa.',false,'Uma negação pode ser verdadeira.'],['Três proposições independentes geram oito linhas na tabela completa.',true,'O número é 2³ = 8.']]);
add('conectivos','rlm','Conectivos, negação e tautologia','Negue a estrutura inteira, respeitando o conectivo.','A conjunção p e q é verdadeira quando ambas são verdadeiras. A disjunção inclusiva é falsa apenas quando ambas são falsas. A condicional p → q é falsa somente em V → F. Negar p e q resulta em não p ou não q. Tautologia é verdadeira em todas as valorações.','"Se estudo, então reviso" só é falsa quando estudo e não reviso. Sua negação é "estudo e não reviso".','Negação da condicional não é simplesmente inverter antecedente e consequente. "Necessariamente" exige validade em todos os casos pertinentes.','O "ou" lógico inclusivo não deve ser trocado por exclusivo sem indicação.','logic',[
['A condicional é falsa quando o antecedente é verdadeiro e o consequente é falso.',true,'É a única linha falsa da implicação material.'],['Negar p e q resulta em não p e não q.',false,'Por De Morgan, a negação é não p ou não q.'],['Uma tautologia é verdadeira em todas as valorações.',true,'Essa é sua definição no modelo proposicional.'],['Na disjunção inclusiva, duas parcelas verdadeiras tornam o todo falso.',false,'Isso seria uma característica do ou exclusivo.']]);
add('conjuntos','rlm','Conjuntos e porcentagens','Defina a base e evite contar a interseção duas vezes.','Na união de dois conjuntos finitos, some as quantidades e subtraia a interseção. Porcentagem é proporção sobre uma base. Variações sucessivas multiplicam fatores, em vez de simplesmente somar taxas. Desconto de 20% seguido de aumento de 20% não retorna ao valor inicial.','100 reduzido em 20% vira 80; acrescido de 20% sobre 80 vira 96.','20% de 80 não é igual a 20% de 100. União inclui todos de A ou B; interseção inclui os comuns.','Identifique a população total, o denominador e eventual sobreposição.','logic',[
['Um desconto de 20% em 100 produz 80.',true,'100 × 0,8 = 80.'],['Aumentar 80 em 20% produz 100.',false,'80 × 1,2 = 96.'],['Ao somar A e B para a união, a interseção foi contada duas vezes.',true,'É preciso subtraí-la uma vez.'],['Toda porcentagem tem a mesma base independentemente do enunciado.',false,'A base é determinada pelo contexto.']]);
add('internet','info','Internet, intranet, navegador e e-mail','Diferencie ferramenta, serviço e infraestrutura.','Navegador acessa recursos da web; mecanismo de busca indexa e localiza conteúdo. Internet é uma rede mundial de redes; intranet aplica tecnologias de rede em ambiente organizacional restrito. Em e-mail, Cc e Cco têm finalidades diferentes. HTTPS protege o transporte, mas não garante a honestidade de um site.','Um site fraudulento pode usar HTTPS. Confira endereço, contexto e solicitação, não apenas o cadeado.','Navegador não é sinônimo de buscador. Intranet não exige que todo recurso seja público.','Recursos e nomes variam por versão; valide as ferramentas cobradas no edital.','info',[
['Navegador e mecanismo de busca são necessariamente o mesmo programa.',false,'Têm funções distintas.'],['Um site com HTTPS pode conter fraude.',true,'A criptografia de transporte não prova legitimidade.'],['Cco pode ocultar destinatários dos demais destinatários.',true,'Essa é uma de suas finalidades.'],['Intranet significa que todos os seus recursos estão abertos ao público.',false,'O acesso pode ser restrito à organização.']]);
add('escritorio','info','Windows e LibreOffice','Aprenda pela função e pela consequência da ação.','Writer edita textos; Calc trabalha com planilhas; Impress cria apresentações. Fórmulas de planilha usam referências que podem ser relativas ou absolutas. Em sistemas operacionais, copiar e mover têm efeitos distintos. Uma ação deve ser interpretada no aplicativo e na versão utilizados.','No Calc, $A$1 é uma referência absoluta; A1 é relativa no comportamento usual de cópia da fórmula.','Copiar um arquivo não é necessariamente movê-lo. Sincronização não equivale sempre a backup independente.','Windows 7/10 são referências históricas do mapa, não afirmação sobre versões exigidas em novo edital.','lo',[
['Writer é voltado à edição de textos.',true,'É o editor de textos do LibreOffice.'],['Impress é o aplicativo de planilhas da suíte.',false,'Planilhas são tratadas no Calc.'],['$A$1 representa referência absoluta no uso usual de planilhas.',true,'Os cifrões fixam coluna e linha.'],['Copiar e mover arquivos produzem sempre o mesmo efeito.',false,'A origem e o destino são afetados de forma distinta.']]);
add('seguranca','info','Segurança, ameaças e backup','Proteção combina prevenção, autenticação e recuperação.','Phishing tenta induzir a vítima a entregar dados ou executar ações. Malware inclui diferentes ameaças, como vírus, worms e ransomware. Senhas únicas, autenticação em dois fatores, atualizações e backups reduzem riscos. Backup deve permitir recuperação, e sua restauração precisa ser testada.','Uma mensagem urgente pede sua senha: confirme o canal e não informe credenciais. Um backup offline pode ajudar em caso de ransomware.','Autenticação verifica identidade; autorização controla o que é permitido. Sincronizar exclusões não preserva necessariamente uma cópia recuperável.','Nenhuma medida isolada garante risco zero. Mantenha cópias separadas e atualizadas.','info',[
['Autenticação em dois fatores elimina todo risco de fraude.',false,'Reduz riscos, mas não oferece garantia absoluta.'],['Phishing pode usar mensagens com aparência legítima.',true,'A engenharia social explora confiança e urgência.'],['Backup deve ser avaliado também pela possibilidade de restauração.',true,'Uma cópia irrecuperável não atende à finalidade.'],['Autenticação e autorização significam exatamente a mesma coisa.',false,'Identificar e permitir ações são funções distintas.']]);
add('etica-deveres','etica','Ética: deveres e vedações','A finalidade pública orienta a conduta, mesmo sem vantagem pessoal.','O Decreto 1.171/1994 aprova o Código de Ética do servidor do Executivo federal. Zelo, honestidade, cortesia e respeito ao cidadão importam. A legalidade não esgota a análise ética. O agente não deve usar o cargo para benefício indevido nem dificultar o exercício regular de direitos.','Atendimento cortês e informação adequada integram a atuação ética, mesmo quando o pedido precisa ser indeferido com fundamento.','Dever ético e infração disciplinar têm regimes próprios; não invente uma penalidade por analogia.','Leia deveres e vedações no decreto, distinguindo juízo ético e processo disciplinar.','e',[
['A cortesia no atendimento é relevante para a ética funcional.',true,'O código trata do respeito ao cidadão.'],['O agente pode usar o cargo para obter benefício indevido.',false,'O uso da função deve atender à finalidade pública.'],['Uma decisão desfavorável dispensa respeito ao cidadão.',false,'A cortesia e o fundamento continuam necessários.'],['A análise ética pode ir além de verificar a formalidade legal.',true,'A dimensão moral da conduta também importa.']]);
add('etica-comissao','etica','Comissões e sistema de gestão da ética','Orientar e apurar ética não autoriza inventar competências.','O Decreto 6.029/2007 institui o Sistema de Gestão da Ética do Executivo federal. As comissões atuam nos limites normativos. No Código de Ética, a pena aplicável pela comissão é a censura, observados os procedimentos. Isso não se confunde com a lista de penalidades do regime disciplinar.','Ao analisar uma sanção, identifique a norma, o órgão competente e o procedimento antes de escolher o nome da pena.','Censura ética não é automaticamente demissão. Comissão de ética não substitui indistintamente todas as instâncias de apuração.','Confira alterações pertinentes e dispositivos específicos. Não misture Decreto 1.171, Decreto 6.029 e Lei 8.112.','et',[
['A comissão de ética pode inventar qualquer penalidade disciplinar.',false,'A competência e as medidas têm previsão normativa.'],['O Decreto 6.029/2007 institui o Sistema de Gestão da Ética.',true,'É sua referência normativa central.'],['Censura ética e demissão são necessariamente a mesma sanção.',false,'São medidas de regimes distintos.'],['Identificar a norma aplicável evita confundir sanções e competências.',true,'Cada regime deve ser respeitado.']]);
